Lemma tpath_msys_ok {St A} : forall n (dec : resp -> option A) (s s' : St) mo tr a mo',
  tpath st (msys n dec s) mo tr (Ok (a, s')) mo' <-> exists rsp, st n mo rsp mo' tr /\ dec rsp = Some a /\ s' = s.
Proof.
