Lemma tpath_msys_any {St A} : forall n (dec : resp -> option A) (s : St) mo tr x mo',
  tpath st (msys n dec s) mo tr x mo' -> exists rsp, st n mo rsp mo' tr /\
    x = match dec rsp with Some a => Ok (a, s) | None => Unr end.
Proof.
